      {/* Rotate key modal */}
      <Dialog open={isRotateKeyModalOpen} setOpen={setIsRotateKeyModalOpen}>
        <DialogContent className=\"max-w-lg\">
          <DialogHeader>
            <DialogTitle>{t(\"workspace.api_keys.rotate\")}</DialogTitle>
          </DialogHeader>
          <DialogBody>
            {rotatedKey ? (
              <>
                <p className=\"mb-2 text-sm text-slate-600\">
                  {t(\"workspace.api_keys.api_key_security_warning\")}
