                        toast.error(t(\"workspace.api_keys.unable_to_copy_api_key\"));
                      }
                    }}
                  />
                </div>
              </>
            ) : (
              <p className=\"text-sm text-slate-600\">
                {t(\"workspace.api_keys.rotate_api_key_confirmation\")}
              </p>
            )}
          </DialogBody>
          <DialogFooter>
            <Button
              type=\"button\"
              variant=\"secondary\"
              onClick={() => {
                setIsRotateKeyModalOpen(false);
                setRotateKey(null);
